#include <iostream>
class Base {
public:
  virtual void func() { std::cout << "Base::func()\n"; }
};
class Derived : public Base {
public:
  void func() override { std::cout << "Derived::func()\n"; }
};
int main() {
  Derived d;
  Base *b = &d;
  b->func(); // Virtual call - runtime polymorphism, uses vtable
  Derived::func(d); //Error: cannot call member function without an object
  d.func(); //Virtual call - runtime polymorphism, uses vtable
  b->Base::func(); // Explicit qualification - compile-time polymorphism, bypasses vtable
  return 0;
}
